INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(14259, 'plPL', 'Chodźcie, intruzi...', '', 0),
(15129, 'plPL', '%s zaczyna uzbrajać bombę zbliżeniową!', '', 0),
(15130, 'plPL', 'Kto śmie przerywać-- Co to ma być? Coście zrobili? Wszystko zniszczycie!', '', 0),
(15132, 'plPL', 'Bliżej! Podejdźcie bliżej... i płońcie!', '', 0),
(17670, 'plPL', 'Tak, jak na to zasługujecie!', '', 0),
(17671, 'plPL', 'Twoi przyjaciele wkrótce do ciebie dołączą!', '', 0),
(17672, 'plPL', 'Powodzenia... Przyda się wam.', '', 0),
(17673, 'plPL', 'Nie wolno wam go uwolnić!', '', 0),
(17674, 'plPL', 'Głupie szczeniaki!', '', 0),
(17675, 'plPL', 'Głupcy! On nas wszystkich pozabija!', '', 0),
(17679, 'plPL', 'Mojej pracy nie wolno przerywać!', '', 0),
(17680, 'plPL', 'Może znajdę dla was jakieś zastosowanie...', '', 0),
(17681, 'plPL', 'Gniew... nienawiść... To narzędzia, których mogę użyć.', '', 0),
(17683, 'plPL', 'Zobaczmy, co da się z was zrobić!', '', 0),
(17684, 'plPL', 'Opór jest bezcelowy.', '', 0),
(17685, 'plPL', 'Trzymajcie się... ode mnie... z dala!', '', 0);
